/**
 * Saved ("predefined") analysis snapshot for offline use.
 *
 * data/offline-analysis.json is generated by `npm run build:offline-analysis`
 * from the demo dataset and committed to the repository. It contains, for
 * every listing, the full Python analysis, the built-in written summary and
 * the SHA-256 of the exact analysis input it was computed from.
 *
 * At runtime it is used ONLY when (a) a live step is unavailable (Python down,
 * Gemini not configured / offline) and (b) the hash of the current input is
 * identical - so a stale snapshot can never show figures that disagree with
 * the statements on screen.
 */
import { createHash } from 'node:crypto';
import { existsSync, readFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

export const SNAPSHOT_PATH = join(dirname(fileURLToPath(import.meta.url)), '..', '..', 'data', 'offline-analysis.json');

let snapshot;
function load() {
  if (snapshot !== undefined) return snapshot;
  try {
    snapshot = existsSync(SNAPSHOT_PATH) ? JSON.parse(readFileSync(SNAPSHOT_PATH, 'utf8')) : null;
  } catch (err) {
    console.warn(`[offline] could not read snapshot: ${err.message}`);
    snapshot = null;
  }
  return snapshot;
}

/** JSON with object keys sorted, so equal data always serialises identically. */
export function canonicalJson(value) {
  if (Array.isArray(value)) return `[${value.map(canonicalJson).join(',')}]`;
  if (value && typeof value === 'object') {
    return `{${Object.keys(value).sort().map((k) => `${JSON.stringify(k)}:${canonicalJson(value[k])}`).join(',')}}`;
  }
  return JSON.stringify(value ?? null);
}

/** Stable hash of an analysis input payload (also used as the analysis cache key). */
export const payloadHash = (payload) => createHash('sha256').update(canonicalJson(payload)).digest('hex');

export function snapshotInfo() {
  const s = load();
  return s ? { generated_at: s.generated_at, provider: s.provider, engine_version: s.engine_version, companies: Object.keys(s.companies).length } : null;
}

/** Saved entry for a symbol, only if it was computed from exactly this input. */
export function findEntry(symbol, inputHash) {
  const entry = load()?.companies?.[symbol];
  return entry && entry.input_hash === inputHash ? entry : null;
}

export function sectorStats(slug) {
  return load()?.sector_stats?.[slug] ?? null;
}

/** Test hook. */
export function setSnapshotForTests(value) {
  snapshot = value;
}
